TextStore.StoredText:
/* Options  */ 
%let srcpath = %nrquote(/PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS);
%let src1 = %nrquote(BAYNO000);

/* List of target columns to keep  */ 
%let keep = ;


/*%let srcpath = /PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS;
%let src = MASKEDS0;*/

%let src = %unquote(&src1);
filename srcfiles pipe "ls &srcpath";

/* Step 1:  Get all the files from the raw source files directory    */
/* Filter out unecessary files based on source system, feed type and */
/* sequence number lengths                                           */

data files_&src;
  infile srcfiles truncover end=last;
  length source_fname $100 source_system feedtype effective_date $8 sequence_no partition_no $5;
  input source_fname $;
  source_system  = substr(source_fname,1,8);
  feedtype       = substr(source_fname,10,8);
  effective_date = substr(source_fname,19,8);
  effective_time = substr(source_fname,27,6);
  sequence_no    = substr(source_fname,34,5);
  partition_no   = substr(source_fname,length(source_fname)-4,1);
run;

proc sort data=files_&src;
by feedtype descending source_fname;
run;

data srcctrl.files_&src;
set files_&src;
length	vld_seqno_flg 
		vld_partition_flg
		vld_header_flg
		vld_trailer_flg
		vld_rec_cnt_flg
		vld_detail_flg
		prc_succ_ind 8;
retain 	vld_seqno_flg 
		vld_partition_flg
		vld_header_flg
		vld_trailer_flg
		vld_rec_cnt_flg
		vld_detail_flg
		prc_succ_ind 0;
by feedtype descending source_fname;
if first.feedtype;
if feedtype eq "BAYNO000";
run;

%rcSet(&syserr); 
%rcSet(&sysrc); 
%rcSet(&sqlrc);

%let src1 = BAYNO000;
%let dsname = SRCCTRL.files_&src1;
%let t_dt = %sysfunc(today());

data _null_;
  length t_dt1 $8.;
  t_dt1 = put(&t_dt,yymmddn8.);
  call symput('t_dt',t_dt1);
run;

%put &t_dt;

*%let t_dt = 20110629;

%put &t_dt;

data vld;
  set &dsname;
  *if effective_date = "&t_dt" then do;
    vld_seqno_flg = 1;
    vld_partition_flg = 1;
  *end;
run;

data &dsname;
  set vld;
run;

/* Options  */ 
%let src1 = BAYNO000;
%let srcpath = %nrquote(/PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS/);

/* List of target columns to keep  */ 
%let keep = ;

/* Step 3: Validate header, trailer, detail */
options invaliddata = 'Z';
/*%let src = MASKEDS0;
%let delim_flg = 0;
%let delmeter = ,;*/

%let src=FMCS0000;
%let dsname = SRCCTRL.files_&src1;
%let vld_header_flg = 0;
%let vld_trailer_flg = 0;
%let vld_rec_cnt_flg = 0;
%let total =0;

/* macro parameters */
*don't forget the \ at then end of the path;

/*%let srcpath = /PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS/;*/

data valid_sources1;
set &dsname;
where vld_seqno_flg = 1 and vld_partition_flg = 1;
run;

* Get additional information:  delimeter;

proc sql noprint;
create table valid_sources as
select a.*, b.delim_flg, b.delmeter
from valid_sources1 a, SRCCTRL.sources b
where a.source_system = b.source_system and
	a.feedtype = b.feedtype;
quit;

data _null_;
  set valid_sources end=last nobs=nobs;
  if nobs > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('total',trim(left(put(i,8.))));
run;

%put &total;

%macro struccheck();
%if &total > 0 %then %do;
%do i = 1 %to &total;
	data _null_;
	set valid_sources (firstobs=&i obs=&i);
	call symput ("fname",source_fname);
	call symput ("src_system",source_system);
	call symput ("feedtype",feedtype);
   * Additional: dec5;
   call symput ("delim_flg",delim_flg);
	call symput ("delmeter", delmeter);
	run;

	%put &fname;
	%put &src_system;
	%put &feedtype;
	%put &delmeter;


	*1) Check file header and footer ;
	%if &delim_flg = 1 %then %do;
		data 	SRCCTRL.&src_system._&feedtype._HEADER
				(keep = source_name
				        record_type  
    	              source_system  
        	 	        feed_type  
          	 	     effective_date 
	          	     effective_time
    	      	     sequence_number
				        errcode)
				SRCCTRL.&src_system._&feedtype._TRAILER 	
				(keep = source_name
				        record_type
				        source_system
				        record_count
				        errcode
				        rec_ctr);

		length source_name $44 RECORD_TYPE detail_rec_type $2 ;
		source_name = "&&src_system";
		infile "&srcpath&&fname" end=done 
				delimiter = "&delmeter"
    			dsd
    			firstobs = 1
    			missover;
		input RECORD_TYPE @;

		if _n_ = 1 then do; * --- HEADER ;
			if RECORD_TYPE = '00' then do;

   				*attrib RECORD_TYPE length = $2 format = $2. informat = $2.; 
   				attrib SOURCE_SYSTEM length = $8 format = $8. informat = $8.; 
   				attrib FEED_TYPE length = $8 format = $8. informat = $8.; 
   				attrib EFFECTIVE_DATE length = 8 format = MMDDYY10. informat = MINGUO8.; 
   				attrib EFFECTIVE_TIME length = 8 format = HHMM5.0 informat = HHMMSS8.; 
   				attrib SEQUENCE_NUMBER length = 4 format = Z5. informat = 5.; 

   				input SOURCE_SYSTEM FEED_TYPE EFFECTIVE_DATE EFFECTIVE_TIME 
        			 SEQUENCE_NUMBER;  
				errcode = _ERROR_; 

				detail_rec_type = '01';

				output SRCCTRL.&src_system._&feedtype._HEADER;
				if errcode eq 0 then vld_header_flg = 1;
					else vld_header_flg = 0;
				end;
				else vld_header_flg = 0;

				call symput("vld_header_flg",vld_header_flg);
			end;
		else do; * --- TRAILER ;
			*put RECORD_TYPE=;
			rec_ctr = _n_;
			if RECORD_TYPE = '99' then do;

				*attrib RECORD_TYPE length = $2 format = $2. informat = $2.; 
   				attrib SOURCE_SYSTEM length = $8 format = $8. informat = $8.; 
   				attrib RECORD_COUNT length = 8 format = 8. informat = 8.; 

   				input /*RECORD_TYPE*/ SOURCE_SYSTEM RECORD_COUNT; 
				errcode = _ERROR_;
 				detail_rec_type = '01';
			   put rec_ctr=;
				put record_count=;
				put source_system=;
				if errcode = 0 then do;
					vld_trailer_flg = 1;
					if record_count > 0 then do;
						if rec_ctr-2 = record_count then vld_rec_cnt_flg = 1;
						else vld_rec_cnt_flg = 0;
					end;
					else do;
						if rec_ctr > 2 then vld_rec_cnt_flg = 0;
						else vld_rec_cnt_flg = 1;
					end;
				end;
				else do;
					vld_trailer_flg = 0;
					vld_rec_cnt_flg = 0;
				end;

				output SRCCTRL.&src_system._&feedtype._TRAILER;
			end;
			else do;
				vld_trailer_flg = 0;
				vld_rec_cnt_flg = 0;
			end;
			call symput("vld_trailer_flg",vld_trailer_flg);
			call symput("vld_rec_cnt_flg",vld_rec_cnt_flg);
		end;
	run;
%end;

%else %do;
	data 	SRCCTRL.&src_system._&feedtype._HEADER	
			(keep = source_name
			        record_type  
    	           source_system  
            	  feed_type  
          	     effective_date 
	              effective_time
    	           sequence_number
			        errcode)
			SRCCTRL.&src_system._&feedtype._TRAILER 	
			(keep = source_name
			        record_type
			        source_system
			        record_count
			        errcode
			        rec_ctr);

	length source_name $44 RECORD_TYPE detail_rec_type $2 ;
	source_name = "&&src_system";
	infile "&srcpath&&fname" end=done ;
	input RECORD_TYPE 1-2 @;

	if _n_ = 1 then do; * --- HEADER ;
		if RECORD_TYPE = '00' then do;
			put "header";
			attrib source_system length = $8; 
	   		attrib feed_type length = $8; 
   			attrib effective_date length = 8 format = mmddyy10. informat = minguo8.; 
   			attrib effective_time length = 8 format = hhmm5.0 informat = hhmmss8.; 
 	  		   attrib sequence_number length = 4 format = z5. informat = 5.; 

	   		input 
    	      	@ 3 source_system  
        	 	   @ 11 feed_type  
          		@ 19 effective_date  minguo8.
	          	@ 27 effective_time  hhmmss8.
    	      	@ 33 sequence_number  5.;  
				errcode = _ERROR_; 

			detail_rec_type = '01';
			output SRCCTRL.&src_system._&feedtype._HEADER;

			if errcode eq 0 then vld_header_flg = 1;
			else vld_header_flg = 0;
			end;

		else vld_header_flg = 0;
		call symput("vld_header_flg",vld_header_flg);
		end;
		*else if not done then do; * --- TRAILER ;
		else do;
			*put RECORD_TYPE=;
			rec_ctr = _n_;
			if RECORD_TYPE = '99' then do;
				put "trailer";
				   attrib source_system length = $8 informat = $8.; 
   				attrib record_count length = 8 informat = 8.; 

				input 
				   @ 3 source_system  $8.
          		@ 11 record_count  8.;
				errcode = _ERROR_;
			   put rec_ctr=;
				put record_count=;

				if errcode = 0 then do;
					vld_trailer_flg = 1;
					if record_count > 0 then do;
						if rec_ctr-2 = record_count then vld_rec_cnt_flg = 1;
						else vld_rec_cnt_flg = 0;
					end;
					else do;
						if rec_ctr > 2 then vld_rec_cnt_flg = 0;
						else vld_rec_cnt_flg = 1;
					end;
				end;
				else do;
					vld_trailer_flg = 0;
					vld_rec_cnt_flg = 0;
				end;

			output SRCCTRL.&src_system._&feedtype._TRAILER;
			end;
			else do;
					vld_trailer_flg = 0;
					vld_rec_cnt_flg = 0;
			end;
			call symput("vld_trailer_flg",vld_trailer_flg);
			call symput("vld_rec_cnt_flg",vld_rec_cnt_flg);
		end;
	run;
%end;

%put &vld_header_flg;
%put &vld_trailer_flg;
%put &vld_rec_cnt_flg;

	data &dsname;
	set &dsname;
	if source_fname = "&fname" then do;
		vld_header_flg = &vld_header_flg;
		vld_trailer_flg = &vld_trailer_flg;
		vld_rec_cnt_flg = &vld_rec_cnt_flg;
	end;
	run;

%end;
%end;
%mend;

%struccheck();


%rcSet(&syserr); 
%rcSet(&sysrc); 
%rcSet(&sqlrc);

/* Options  */ 
%let src1 = BAYNO000;
%let srcpath = %nrquote(/PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS/);
%let incpath = %nrquote(/PROJECT_A/07_scripts/File Validation/);
%let errthresh = %nrquote(20);

/* List of target columns to keep  */ 
%let keep = ;

/* Step 4: Validate detail structure*/
options invaliddata = 'Z';
options error=max;
/*%let src = MASKEDS0;
%let srcpath = /PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS/;  *--don't forget \ at the end;
%let incpath = /PROJECT_A/07_scripts/File Validation/; *--don't forget \ at the end;
%let delim_flg = 0;
%let delmeter = ,;
%let errthresh = 20;*/
%let total =0;
%let vld_detail_flg=0;


%let src = FMCS0000;
%let dsname = SRCCTRL.files_&src1;

data valid_sources1;
set &dsname;
where vld_seqno_flg = 1 and vld_partition_flg = 1;
run;

* Get additional information:  delimeter;

proc sql noprint;
create table valid_sources as
select a.*, b.delim_flg, b.delmeter
from valid_sources1 a, SRCCTRL.sources b
where a.source_system = b.source_system and
	a.feedtype = b.feedtype;
quit;


data _null_;
  set valid_sources end=last;
  if _n_ > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('total',trim(left(put(i,8.))));
run;

%put &total;

%macro detcheck();
%if &total > 0 %then %do;
	%do i = 1 %to &total;
		data _null_;
		set valid_sources (firstobs=&i obs=&i);
		call symput ("fname",source_fname);
		call symput ("src_system",source_system);
		call symput ("feedtype",feedtype);
	   call symput ("delim_flg", delim_flg);
	   call symput ("delmeter", delmeter);
		run;

		%put &fname;
		%put &src_system;
		%put &feedtype;
		%put &delmeter;
		%let srcfile = &srcpath&fname;
		%let incfile = &incpath&src_system._&feedtype._STRUCTURE.TXT;
		%let dsout = SRCCTRL.&src_system._&feedtype._INVALID_RECS;

*1) Check details ;
/*%if &delim_flg = 1 %then %do;
%end;
%else %do;
	%include "&incfile";
%end;
%end*/
		%include "&incfile";



* Compute for error percentage;

		proc summary data=&dsout nway;
		var errorcode;
		output out = temp1 (drop=_type_) sum=;
		run;

		data temp2;
		set temp1;
		if errorcode > 0 then do;
			err_cnt =(errorcode/_freq_)*100;
		end;
		else err_cnt = 0;
		if err_cnt > &errthresh then vld_detail_flg = 0;
		else vld_detail_flg = 1;
		call symput("vld_detail_flg", vld_detail_flg);
		put err_cnt=;
		format err_cnt COMMA6.2;
		run;

		%put &errthresh;
		%put &feedtype;
		%put &vld_detail_flg;

		data &dsname;
		set &dsname;
		if source_fname = "&fname" then do;
			vld_detail_flg = &vld_detail_flg;
		end;
		run;

		data &dsout;
		length fname $100 file_row_num 8;
		set &dsout;
		fname = "&fname";
		file_row_num = _n_;
		if errorcode = 1 then output;
		run;
	%end;
%end;
%mend;

%detcheck();



%rcSet(&syserr); 
%rcSet(&sysrc); 
%rcSet(&sqlrc);

/* Options  */ 
%let srcpath = %nrquote(/PROJECT_A/01_source_layer/01_raw_source_files/MASKEDS/);
%let vld_path = %nrquote(/PROJECT_A/01_source_layer/02_valid_source_files/MASKEDS/);
%let invld_path = %nrquote(/PROJECT_A/01_source_layer/03_invalid_source_files/MASKEDS/);
%let src1 = BAYNO000;
%let vld_total_ctr = %nrquote(1);

%let src = FMCS0000;
%let dsname = SRCCTRL.FILES_&src1;
%let invalid_flg = 0;
%let ivld_total = 0;
%let ivld_total_ctr = 0;
%let vld_total = 0;

%put &dsname;

data ds_valid1 ds_invalid1;
set &dsname nobs=nobs;
put nobs=;
if 	vld_seqno_flg = 1 and 
	vld_partition_flg = 1 and 
	vld_header_flg = 1 and 
	vld_trailer_flg = 1 and 
	vld_rec_cnt_flg = 1 and 
	vld_detail_flg = 1 then do;
	* move file to valid folder;
	* split header, details, trailer;
	output ds_valid1;
end;
else do;
	* move file to invalid folder;
	output ds_invalid1;
end;
run;


* Get additional information:  delimeter;

proc sql noprint;
create table ds_valid as
select a.*, b.delim_flg, b.delmeter, b.lreclength
from ds_valid1 a, SRCCTRL.sources b
where a.source_system = b.source_system and
	a.feedtype = b.feedtype;
quit;

proc sql noprint;
create table ds_invalid as
select a.*, b.delim_flg, b.delmeter, b.lreclength
from ds_invalid1 a, SRCCTRL.sources b
where a.source_system = b.source_system and
	a.feedtype = b.feedtype;
quit;


* Get number of valid files;
data _null_;
  set ds_valid end=last nobs=nobs;
  if nobs > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('vld_total',trim(left(put(i,8.))));
run;

%put &vld_total;

* Get number of invalid files;
data _null_;
  set ds_invalid end=last nobs=nobs;
  if nobs > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('ivld_total',trim(left(put(i,8.))));
run;

%put &ivld_total;


%macro htdet (srcname,src_system,feedtype);
%if &delim_flg = 0 %then %do;
data hdtrlib.&src_system._&feedtype._HEADER	(keep = source_name
										RECORD_TYPE  
    	      							source_system  
        	 							feed_type  
          								effective_date 
	          							effective_time
    	      							sequence_number
        	  							partition_number  
          								partition_flag
										errcode
										detail_rec_type)
		hdtrlib.&src_system._&feedtype._TRAILER 		(keep = source_name
										RECORD_TYPE
										source_system
										record_count
										errcode
										detail_rec_type);

		length source_name $44 RECORD_TYPE detail_rec_type $2 ;
		source_name = "&&src_system";
		infile "&srcpath&&srcname" end=done ;
		input RECORD_TYPE 1-2 @;

		if _n_ = 1 then do; * --- HEADER ;
			if RECORD_TYPE = '00' then do;

			attrib source_system length = $8; 
	   		attrib feed_type length = $8; 
   			attrib effective_date length = 8 format = mmddyy10. informat = minguo8.; 
   			attrib effective_time length = 8 format = hhmm5.0 informat = hhmmss8.; 
 	  		attrib sequence_number length = 4 format = z5. informat = 5.; 
   			attrib partition_number length = 4; 
			attrib partition_flag length = $1; 

	   		input 
    	      	@ 3 source_system  
        	 	@ 11 feed_type  
          		@ 19 effective_date  minguo8.
	          	@ 27 effective_time  hhmmss8.
    	      	@ 33 sequence_number  5.
        	  	@ 38 partition_number  
          		@ 39 partition_flag;  

			errcode = _ERROR_; 
			detail_rec_type = '01';
			output hdtrlib.&src_system._&feedtype._HEADER;
			end;
		end;

		else do; * --- TRAILER ;
			put RECORD_TYPE=;
			if RECORD_TYPE = '99' then do;

				attrib source_system length = $8 informat = $8.; 
   				attrib record_count length = 8 informat = 8.; 

				input 
				@ 3 source_system  $8.
          		@ 11 record_count  8.;
 			detail_rec_type = '01';
   			output hdtrlib.&src_system._&feedtype._TRAILER;
			end;
		end;
run;
%end;
%else %do;
data hdtrlib.&src_system._&feedtype._HEADER	(keep = source_name
										RECORD_TYPE  
    	      							source_system  
        	 							feed_type  
          								effective_date 
	          							effective_time
    	      							sequence_number
        	  							partition_number  
          								partition_flag
										errcode
										detail_rec_type)
		hdtrlib.&src_system._&feedtype._TRAILER 		(keep = source_name
										RECORD_TYPE
										source_system
										record_count
										errcode
										detail_rec_type);

		length source_name $44 RECORD_TYPE detail_rec_type $2 ;
		source_name = "&&src_system";
		infile "&srcpath&&srcname" end=done 
		          delimiter = "&delmeter"
        		     dsd
          		  firstobs = 1
          		  missover;
		input RECORD_TYPE @;

		if _n_ = 1 then do; * --- HEADER ;
			if RECORD_TYPE = '00' then do;

   			attrib SOURCE_SYSTEM length = $8 format = $8. informat = $8.; 
   			attrib FEED_TYPE length = $8 format = $8. informat = $8.; 
   			attrib EFFECTIVE_DATE length = 8 format = MMDDYY10. informat = MINGUO8.; 
   			attrib EFFECTIVE_TIME length = 8 format = HHMM5.0 informat = HHMMSS8.; 
   			attrib SEQUENCE_NUMBER length = 4 format = Z5. informat = 5.; 
   			attrib PARTITION_NUMBER length = 4 format = 1. informat = 1.; 
   			attrib PARTITION_FLAG length = $1 format = $1. informat = $1.; 

   			input /*RECTYPE*/ SOURCE_SYSTEM FEED_TYPE EFFECTIVE_DATE EFFECTIVE_TIME 
        			 SEQUENCE_NUMBER PARTITION_NUMBER PARTITION_FLAG; 

			errcode = _ERROR_; 
			detail_rec_type = '01';
			output hdtrlib.&src_system._&feedtype._HEADER;
			end;
		end;

		else /*if not done then*/ do; * --- TRAILER ;
			*put RECORD_TYPE=;
			if RECORD_TYPE = '99' then do;

			*attrib RECTYPE length = $2 format = $2. informat = $2.; 
   			attrib SOURCE_SYSTEM length = $8 format = $8. informat = $8.; 
   			attrib RECORD_COUNT length = 8 format = 3. informat = 3.; 

   			input /*RECTYPE*/ SOURCE_SYSTEM RECORD_COUNT; 

 			detail_rec_type = '01';
   			output hdtrlib.&src_system._&feedtype._TRAILER;
			end;
		end;
run;
%end;
%mend ;

%macro movefiles(invalid_flg,ds,total,total_ctr);
%put "-----------------------------";
%put &ds;
%put &invalid_flg;
%put "-----------------------------";

* Step a:  Check whether the required number of files for valid ;
* matches the total of valid files ;
* If yes, then continue to process the valid files;

%if &&&total >= &&&total_ctr %then %do;
	%if &invalid_flg = 0 %then %do;
		%do i = 1 %to &&&total;
			data _null_;
			set &ds (firstobs=&i obs=&i);
			call symput ("fname",source_fname);
			call symput ("src_system",source_system);
			call symput ("feedtype",feedtype);
		   call symput ("delim_flg", delim_flg);
			call symput ("delmeter", delmeter);
			call symput ("lreclength",lreclength);
			run;

			%put &fname;
			%put &src_system;
			%put &feedtype;

			***Split header, details, trailer;
			data _null_;
			infile "&srcpath&fname"
				firstobs=2 _infile_=x end=done LRECL=&lreclength;
			input;
			if not done then do;
  		  		if substr(x,1,2) = '01' then do;
					file "&vld_path&src_system._&feedtype._DETAILS.DAT" LRECL=&lreclength;
					put x;
				end;
			end;
			run;

			%htdet (&fname,&src_system,&feedtype);

			***Move file;
			data _null_;
				command = "mv &srcpath&fname &vld_path";
				put command=;
				call system (command);
			run;
		%end;
	%end;
	%else %do;
		%do i = 1 %to &&&total;
			data _null_;
			set &ds (firstobs=&i obs=&i);
			call symput ("fname",source_fname);
			call symput ("src_system",source_system);
			call symput ("feedtype",feedtype);
		   call symput ("delim_flg", delim_flg);
			call symput ("delmeter", delmeter);
			call symput ("lreclength",lreclength);
			run;

			%put "------------";
			%put &fname;
			%put &src_system;
			%put &feedtype;
			%put "------------";

			***Move file;
			data _null_;
				command = "mv &srcpath&fname &invld_path ";
				put command=;
				call system (command);
			run;
		%end;
	%end;
%end;

* If the total number of valid files does not match the required;
* then move all the valid files to invalid folder ;

%if &&&total < &&&total_ctr %then %do;
	%if &invalid_flg = 0 %then %do;

		%do i = 1 %to &&&total;
			data _null_;
			set &ds (firstobs=&i obs=&i);
			call symput ("fname",source_fname);
			call symput ("src_system",source_system);
			call symput ("feedtype",feedtype);
		   call symput ("delim_flg", delim_flg);
			call symput ("delmeter", delmeter);
			call symput ("lreclength",lreclength);
			run;
   		%put "------------";
			%put &fname;
			%put &src_system;
			%put &feedtype;
			%put "------------";

			***Move file;
			data _null_;
			command = "mv &srcpath&fname &invld_path ";
			put command=;
			call system (command);
			run;
		%end;
	%end;
%end;
%mend;


%movefiles(1,ds_invalid,ivld_total,ivld_total_ctr);
%movefiles(0,ds_valid,vld_total,vld_total_ctr);

%rcSet(&syserr); 
%rcSet(&sysrc); 
%rcSet(&sqlrc);

/* Options  */ 
%let src1 = BAYNO000;
%let vld_total_ctr = %nrquote(1);

* Step 6: Issue an exit if there is no valid file to process;

%let src = FMCS0000;
%let dsname = SRCCTRL.FILES_&src1;
%let ivld_total = 0;
%let vld_total = 0;

%put &dsname;

data ds_valid1 ds_invalid1;
set &dsname nobs=nobs;
put nobs=;
if 	vld_seqno_flg = 1 and 
	vld_partition_flg = 1 and 
	vld_header_flg = 1 and 
	vld_trailer_flg = 1 and 
	vld_rec_cnt_flg = 1 and 
	vld_detail_flg = 1 then do;
	* move file to valid folder;
	* split header, details, trailer;
	output ds_valid1;
end;
else do;
	* move file to invalid folder;
	output ds_invalid1;
end;
run;

* Get additional information:  delimeter;

proc sql noprint;
create table ds_valid as
select a.*, b.delim_flg, b.delmeter, b.lreclength
from ds_valid1 a, SRCCTRL.sources b
where a.source_system = b.source_system and
	a.feedtype = b.feedtype;
quit;

* Get number of valid files;
data _null_;
  set ds_valid end=last nobs=nobs;
  if nobs > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('vld_total',trim(left(put(i,8.))));
run;

%put &vld_total;

%macro do_abort(total,total_ctr);
* If the total number of valid files does not match the required;
* then issue an abort/exit ;

%if &&&total < &&&total_ctr %then %do;
	data _null;
		abort;
	run;
%end;
%mend;


%do_abort(vld_total,vld_total_ctr);

%rcSet(&syserr); 
%rcSet(&sysrc); 
%rcSet(&sqlrc);

/* Options  */ 
%let vld_path = %nrquote(/PROJECT_A/01_source_layer/02_valid_source_files/MASKEDS/);
%let prc_path = %nrquote(/PROJECT_A/01_source_layer/05_processed_source_files/MASKEDS/);
%let src1 = BAYNO000;

%let src = BAYNO000;
%let dsname = SRCCTRL.files_&src1;

* Check whether data was successfully loaded before proceeding with ;
* succeeding codes;

data ds_valid;
set &dsname nobs=nobs;
put nobs=;
if 	vld_seqno_flg = 1 and 
	vld_partition_flg = 1 and 
	vld_header_flg = 1 and 
	vld_trailer_flg = 1 and 
	vld_rec_cnt_flg = 1 and 
	vld_detail_flg = 1;
run;

* Get number of valid files;
data _null_;
  set ds_valid end=last nobs=nobs;
  if nobs > 0 then do;
		i+1;
		put i=;
  end;
  if last then call symput('vld_total',trim(left(put(i,8.))));
run;

%put &vld_total;

%macro move_prc();
%do i = 1 %to &vld_total;
	data _null_;
	set ds_valid (firstobs=&i obs=&i);
	call symput ("fname",source_fname);
	call symput ("src_system",source_system);
	call symput ("feedtype",feedtype);
	run;
   %put "------------";
	%put &fname;
	%put &src_system;
	%put &feedtype;
	%put "------------";

	***Move file;
	data _null_;
		command = "mv &vld_path&fname &prc_path ";
		put command=;
		call system (command);
	run;

	data SRCCTRL.files_&src;
	set SRCCTRL.files_&src;
	if source_fname = "&fname" then prc_succ_ind = 1;
   run;

%end;
%mend;

